-- composition of rule kernels BloomFilter x ExistsToJoin (sqlite), template exists
SELECT count(*) FROM (WITH RECURSIVE rc(c0) AS (SELECT 1 UNION ALL SELECT r.c0 + 1 FROM rc AS r WHERE r.c0 < 5) SELECT TRUE AS c0, CAST('a' AS TEXT) AS c1 UNION ALL SELECT ('2000-01-01 00:00:00' IN (SELECT '1970-01-01 00:00:00' AS c0)) AS c0, CAST('%' AS TEXT) AS c1 FROM rc AS a1) AS ka WHERE EXISTS (SELECT 1 FROM (SELECT '{"k": -1, "a": [1, 2, 3]}' AS c0, '2024-01-01 00:00:00' AS c1 FROM t0 AS a1 WHERE (EXISTS (SELECT a1.c1 AS c0, a2.c0 AS c1, a1.c1 AS c2 FROM t1 AS a2))) AS kb);
-- pgfuzz:check kernel:exists SELECT CASE WHEN (SELECT count(*) FROM (SELECT '{"k": -1, "a": [1, 2, 3]}' AS c0, '2024-01-01 00:00:00' AS c1 FROM t0 AS a1 WHERE (EXISTS (SELECT a1.c1 AS c0, a2.c0 AS c1, a1.c1 AS c2 FROM t1 AS a2))) AS kb) > 0 THEN (SELECT count(*) FROM (WITH RECURSIVE rc(c0) AS (SELECT 1 UNION ALL SELECT r.c0 + 1 FROM rc AS r WHERE r.c0 < 5) SELECT TRUE AS c0, CAST('a' AS TEXT) AS c1 UNION ALL SELECT ('2000-01-01 00:00:00' IN (SELECT '1970-01-01 00:00:00' AS c0)) AS c0, CAST('%' AS TEXT) AS c1 FROM rc AS a1) AS ka) ELSE 0 END
